#!/bin/bash
# ============================================================
# update47.sh
# 新增「內線互撥」自訂 Dialplan 範本（限定分機清單，供 TC-ACSBC 等
# 自訂 context 使用），並修復兩個既有 bug：
#   1. TemplateCreateRequest.context 寫死 Literal["default","public"]，
#      導致範本模式完全無法寫入其他自訂 context（跟前端「Context 選單
#      支援任意既有 context」的實際行為互相矛盾，TC-ACSBC 也受影響）
#   2. list_custom_files() 只掃描 default/public，自訂 context 裡的
#      範本檔案永遠不會出現在列表
#   3. 新增輕量分機清單端點（不含密碼欄位），供範本表單勾選分機用
# 對應：changelog-details/20260811-internal-extension-template.md
#
# 修改檔案：routers/dialplan_custom.py（整份覆寫）、
#           static/js/dialplan.js（精確字串替換）
# ============================================================
set -e

cd "$(dirname "$0")"

BACKEND="routers/dialplan_custom.py"
FRONTEND="static/js/dialplan.js"

# --- 0. 自動歸檔：把非本次腳本的其他 updateN.sh 搬進固定資料夾 ---
ARCHIVE_DIR="updateN"
SELF="$(basename "$0")"

mkdir -p "$ARCHIVE_DIR"
for f in update*.sh; do
  [ "$f" = "$SELF" ] && continue
  [ -f "$f" ] || continue
  git mv "$f" "${ARCHIVE_DIR}/$f" 2>/dev/null || mv "$f" "${ARCHIVE_DIR}/$f"
done
git add update*.sh "$ARCHIVE_DIR"/ 2>/dev/null || true
if ! git diff --cached --quiet 2>/dev/null; then
  git commit -m "chore: 歸檔已執行的 updateN.sh 腳本"
fi

# --- 1. 前置驗證 ---
echo "[前置驗證] 確認兩個目標檔案目前內容符合預期（尚未套用本次改動）..."

for f in "$BACKEND" "$FRONTEND"; do
  if [ ! -f "$f" ]; then
    echo "❌ 找不到 $f" >&2
    exit 1
  fi
done

if grep -q "internal_extension" "$BACKEND"; then
  echo "❌ $BACKEND 已包含 internal_extension，本次改動可能已套用過，中止避免重複套用" >&2
  exit 1
fi

if grep -q '_dcPopulateDynamicFields' "$FRONTEND"; then
  echo "❌ $FRONTEND 已包含 _dcPopulateDynamicFields，本次改動可能已套用過，中止避免重複套用" >&2
  exit 1
fi

if ! grep -q 'context: Literal\["default", "public"\]' "$BACKEND"; then
  echo "❌ $BACKEND 內容與預期的舊版不符（找不到比對錨點），請先確認檔案目前實際內容，不要假設等於文件記錄的版本" >&2
  exit 1
fi

echo "  ✓ 前置驗證通過"

# --- 2. routers/dialplan_custom.py：整份覆寫（base64 還原，避免 SSH heredoc 貼上內容被截斷/打亂）---
echo "[Step 1] 覆寫 $BACKEND..."
cp "$BACKEND" "${BACKEND}.pre-update47.bak"

echo "" | base64 -d > routers/dialplan_custom.py

if [ ! -s routers/dialplan_custom.py ]; then
  echo "❌ routers/dialplan_custom.py 覆寫後為空檔案，還原備份並中止" >&2
  cp routers/dialplan_custom.py.pre-update47.bak routers/dialplan_custom.py
  exit 1
fi

# --- 3. static/js/dialplan.js：精確字串替換（4 處）---
echo "[Step 2] 套用 static/js/dialplan.js 改動..."
cp static/js/dialplan.js static/js/dialplan.js.pre-update47.bak

python3 << 'PYEOF_JS'
import sys

path = "static/js/dialplan.js"
with open(path, "r", encoding="utf-8") as f:
    content = f.read()

edits = []

# Edit 1: _dcRenderRoot 新增 async 動態欄位填充
old1 = """function _dcRenderRoot() {
  const root = document.getElementById(_dcMountId);
  if (_dcMode === 'list') {
    root.innerHTML = _dcListPanelHtml();
  } else if (_dcMode === 'pick') {
    root.innerHTML = _dcPickerPanelHtml();
  } else {
    root.innerHTML = _dcFormPanelHtml();
    _dcBindFormEvents();
    _dcUpdatePreview();
  }
}"""
new1 = """function _dcRenderRoot() {
  const root = document.getElementById(_dcMountId);
  if (_dcMode === 'list') {
    root.innerHTML = _dcListPanelHtml();
  } else if (_dcMode === 'pick') {
    root.innerHTML = _dcPickerPanelHtml();
  } else {
    root.innerHTML = _dcFormPanelHtml();
    _dcBindFormEvents();
    _dcUpdatePreview();
    _dcPopulateDynamicFields();
  }
}"""
edits.append(("_dcRenderRoot", old1, new1))

# Edit 2: _dcFieldInputHtml 新增 dynamic_multiselect 型別
old2 = """function _dcFieldInputHtml(field, value) {
  const v = value !== undefined && value !== null ? value : '';
  const common = `id="dc-field-${field.key}" data-key="${field.key}" class="settings-input" style="max-width:320px"`;
  if (field.type === 'select') {"""
new2 = """function _dcFieldInputHtml(field, value) {
  const v = value !== undefined && value !== null ? value : '';
  const common = `id="dc-field-${field.key}" data-key="${field.key}" class="settings-input" style="max-width:320px"`;
  if (field.type === 'dynamic_multiselect') {
    // 選項要向後端即時抓取（如分機清單），此處先給占位容器，
    // 實際內容由 _dcPopulateDynamicFields() 在表單插入 DOM 後非同步填入。
    // data-prefill 保留編輯模式回填用的既有選中值（逗號分隔）。
    return `<div id="dc-field-${field.key}" data-key="${field.key}"
                 data-source="${_escAttr(field.source || '')}"
                 data-prefill="${_escAttr(v)}"
                 style="max-width:420px;border:1px solid var(--border);border-radius:4px;
                        padding:8px;max-height:180px;overflow-y:auto;background:var(--panel2)">
              <div style="font-size:12px;color:var(--muted)">載入中...</div>
            </div>`;
  }
  if (field.type === 'select') {"""
edits.append(("_dcFieldInputHtml", old2, new2))

# Edit 3: _dcBindFormEvents 對 dynamic_multiselect 改綁 change 事件
old3 = """function _dcBindFormEvents() {
  const tpl = _dcCurrentTemplate();
  if (!tpl) return;
  tpl.fields.forEach(f => {
    const el = document.getElementById(`dc-field-${f.key}`);
    if (el) el.addEventListener('input', _dcSchedulePreview);
  });
}"""
new3 = """function _dcBindFormEvents() {
  const tpl = _dcCurrentTemplate();
  if (!tpl) return;
  tpl.fields.forEach(f => {
    const el = document.getElementById(`dc-field-${f.key}`);
    if (!el) return;
    // dynamic_multiselect 的容器本身不是 input，勾選框是事後非同步塞進去的，
    // 用 change 事件冒泡監聽整個容器即可涵蓋所有勾選框，不需要逐一綁定
    const evt = f.type === 'dynamic_multiselect' ? 'change' : 'input';
    el.addEventListener(evt, _dcSchedulePreview);
  });
}"""
edits.append(("_dcBindFormEvents", old3, new3))

# Edit 4: _dcCollectValues 改支援 dynamic_multiselect + 新增兩個輔助函式
old4 = """function _dcCollectValues() {
  const tpl = _dcCurrentTemplate();
  const values = {};
  (tpl?.fields || []).forEach(f => {
    const el = document.getElementById(`dc-field-${f.key}`);
    values[f.key] = el ? el.value.trim() : '';
  });
  return values;
}"""
new4 = """function _dcCollectValues() {
  const tpl = _dcCurrentTemplate();
  const values = {};
  (tpl?.fields || []).forEach(f => {
    if (f.type === 'dynamic_multiselect') {
      const container = document.getElementById(`dc-field-${f.key}`);
      const checked = container
        ? Array.from(container.querySelectorAll('input[type="checkbox"]:checked')).map(cb => cb.value)
        : [];
      values[f.key] = checked.join(',');
      return;
    }
    const el = document.getElementById(`dc-field-${f.key}`);
    values[f.key] = el ? el.value.trim() : '';
  });
  return values;
}

// ── dynamic_multiselect 欄位：非同步載入選項 ─────────────────────────────────
async function _dcPopulateDynamicFields() {
  const tpl = _dcCurrentTemplate();
  if (!tpl) return;
  const dynFields = tpl.fields.filter(f => f.type === 'dynamic_multiselect');

  for (const f of dynFields) {
    const container = document.getElementById(`dc-field-${f.key}`);
    if (!container) continue;

    const prefillRaw = container.getAttribute('data-prefill') || '';
    const prefillSet = new Set(prefillRaw.split(',').map(s => s.trim()).filter(Boolean));

    try {
      let options = [];
      if (f.source === 'extensions') {
        const data = await apiFetch('/api/dialplan/custom/extension-options');
        options = (data && data.extensions) ? data.extensions : [];
      }

      if (!options.length) {
        container.innerHTML = `<div style="font-size:12px;color:var(--muted)">（目前沒有可選項目）</div>`;
        continue;
      }

      const filterId = `dc-filter-${f.key}`;
      const listId   = `dc-list-${f.key}`;
      container.innerHTML = `
        <input id="${filterId}" class="settings-input" style="width:100%;box-sizing:border-box;
               margin-bottom:6px;font-size:12px" placeholder="搜尋分機號碼或名稱..."
               oninput="_dcFilterDynamicOptions('${listId}', this.value)">
        <div id="${listId}">
          ${options.map(o => `
            <label style="display:flex;align-items:center;gap:6px;padding:3px 0;font-size:12px;cursor:pointer"
                   data-search="${_escAttr((o.id + ' ' + (o.caller_id_name || '')).toLowerCase())}">
              <input type="checkbox" value="${_escAttr(o.id)}" ${prefillSet.has(String(o.id)) ? 'checked' : ''}>
              <span>${_escHtml(o.id)}${o.caller_id_name ? ` <span style="color:var(--muted)">(${_escHtml(o.caller_id_name)})</span>` : ''}</span>
            </label>`).join('')}
        </div>`;
    } catch (e) {
      container.innerHTML = `<div style="font-size:12px;color:var(--red)">載入失敗：${_escHtml(e.message)}</div>`;
    }
  }

  // 選項填好後，若編輯模式已有預選值，觸發一次預覽更新
  if (dynFields.length) _dcSchedulePreview();
}

function _dcFilterDynamicOptions(listId, keyword) {
  const kw = (keyword || '').trim().toLowerCase();
  const list = document.getElementById(listId);
  if (!list) return;
  Array.from(list.children).forEach(label => {
    const hay = label.getAttribute('data-search') || '';
    label.style.display = (!kw || hay.includes(kw)) ? 'flex' : 'none';
  });
}"""
edits.append(("_dcCollectValues", old4, new4))

for name, old, new in edits:
    count = content.count(old)
    if count != 1:
        print(f"❌ 比對錨點「{name}」在檔案中出現 {count} 次（預期 1 次），中止，不寫入任何檔案", file=sys.stderr)
        sys.exit(1)
    content = content.replace(old, new)

with open(path, "w", encoding="utf-8") as f:
    f.write(content)

print("  ✓ static/js/dialplan.js 四處改動皆已套用")
PYEOF_JS

if [ $? -ne 0 ]; then
  echo "❌ static/js/dialplan.js 字串替換失敗，還原全部備份並中止" >&2
  cp static/js/dialplan.js.pre-update47.bak static/js/dialplan.js
  cp routers/dialplan_custom.py.pre-update47.bak routers/dialplan_custom.py
  exit 1
fi

# --- 4. 語法驗證 ---
echo "[Step 3] 語法檢查..."
PY=python3
command -v /opt/myapp/venv/bin/python3 >/dev/null 2>&1 && PY=/opt/myapp/venv/bin/python3

$PY -c "import ast; ast.parse(open('routers/dialplan_custom.py').read())" \
  && echo "  ✓ routers/dialplan_custom.py 語法檢查通過" \
  || {
    echo "❌ routers/dialplan_custom.py 語法檢查失敗，還原全部備份" >&2
    cp static/js/dialplan.js.pre-update47.bak static/js/dialplan.js
    cp routers/dialplan_custom.py.pre-update47.bak routers/dialplan_custom.py
    exit 1
  }

if command -v node >/dev/null 2>&1; then
  node -c static/js/dialplan.js \
    && echo "  ✓ static/js/dialplan.js 語法檢查通過" \
    || {
      echo "❌ static/js/dialplan.js 語法檢查失敗，還原全部備份" >&2
      cp static/js/dialplan.js.pre-update47.bak static/js/dialplan.js
      cp routers/dialplan_custom.py.pre-update47.bak routers/dialplan_custom.py
      exit 1
    }
else
  echo "  ⚠ 找不到 node，略過前端語法檢查（建議部署後在瀏覽器 F12 Console 確認無語法錯誤）"
fi

# --- 5. 清掉備份檔（確認語法都過了才清）---
rm -f routers/dialplan_custom.py.pre-update47.bak static/js/dialplan.js.pre-update47.bak

# --- 6. git commit ---
echo "[Step 4] git commit..."
git add routers/dialplan_custom.py static/js/dialplan.js
git status
git commit -m "feat: 新增「內線互撥」自訂 Dialplan 範本（限定分機清單），修復範本模式無法寫入 default/public 以外 context 的既有 bug，新增不含密碼的輕量分機清單端點供表單勾選"

echo ""
echo "======================================================"
echo " ✓ update47.sh 執行完成"
echo ""
git log --oneline -1
echo ""
echo " ⚠️ 本次修改 routers/dialplan_custom.py（後端），依慣例需要重啟服務："
echo "    systemctl restart fs-dashboard"
echo "    static/js/dialplan.js 是純前端檔案，瀏覽器強制重新整理即可，不需要重啟服務"
echo ""
echo " 驗證重點清單："
echo "  1. systemctl restart fs-dashboard 後 systemctl status fs-dashboard 確認正常啟動、無 500"
echo "  2. 確認新端點正常（應回傳分機清單，不含 password/vm_password 欄位）："
echo "     curl -s http://127.0.0.1:3000/api/dialplan/custom/extension-options -H \"Authorization: Bearer <token>\""
echo "  3. 確認既有範本（時段路由/黑名單）仍正常運作，沒有被新改動影響"
echo "  4. 到「自定義 Dialplan」頁面 → 從範本建立 → 應該看到「內線互撥（限定分機清單）」新選項"
echo "  5. 選擇「內線互撥」範本，Context 選 TC-ACSBC（驗證舊 bug 已修復，之前選這個會被 422 擋掉）："
echo "     - 分機勾選框應該正確載入分機清單（不是卡在「載入中...」）"
echo "     - 搜尋框輸入分機號碼應該能篩選"
echo "     - 勾選 1126、1210 後「進階：檢視產生的 Dialplan XML」應該即時更新預覽"
echo "     - 儲存成功後，實際撥打 1126→1210 應該要能接通"
echo "  6. 確認「自定義 Dialplan」列表頁能看到 TC-ACSBC 底下建立的檔案（驗證 list_custom_files 修復）"
echo "  7. 確認 push 前 git status 乾淨、git log 看到本次 feat: commit"
echo "  8. push 由你自己手動執行"
echo "======================================================"
